const STORE='rahcode-demo-v1';
async function api(path,body,timeoutMs=65000){let response,controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeoutMs);try{response=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,signal:controller.signal})}catch(error){if(error.name==='AbortError')throw new Error('پاسخ سرور بیش از زمان مجاز طول کشید. اتصال سرور را بررسی کنید و دوباره تلاش کنید.');throw new Error('به سرور محلی وصل نشدیم؛ دمو را با دستور npm start اجرا کنید.')}finally{clearTimeout(timer)}let data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'درخواست ناموفق بود.');return data}
const moduleNames=['آشنایی با پایتون','متغیرها و انواع داده','ورودی و خروجی','شرط‌ها','حلقه‌ها','رشته‌ها و لیست‌ها','توابع','دیکشنری‌ها و مجموعه‌ها','فایل‌ها و خطاها','پروژه پایانی'];
const lessonNames=[['پایتون چیست؟','نصب و اجرای پایتون','اولین برنامه'],['متغیرها','عددها و محاسبات','نوع داده'],['نمایش خروجی','گرفتن ورودی','ساخت ماشین‌حساب'],['شرط if','else و elif','تمرین تصمیم‌گیری'],['حلقه for','حلقه while','الگوهای تکرار'],['کار با رشته‌ها','ساخت لیست','پیمایش لیست'],['تعریف تابع','پارامتر و بازگشت','توابع کاربردی'],['ساخت دیکشنری','کار با مجموعه‌ها'],['خواندن فایل','مدیریت خطا'],['طراحی برنامه','ساخت دفترچه یادداشت','مرور و جمع‌بندی']];
const moduleLessons=moduleNames.map((m,i)=>lessonNames[i].map((n,j)=>({id:`l${i+1}-${j+1}`,name:n,module:i+1,done:false,blocks:[{type:'heading',text:n},{type:'text',text:`در این درس با ${n} در پایتون آشنا می‌شویم. ابتدا مفهوم را با یک مثال ساده بررسی می‌کنیم و سپس خودتان آن را تمرین می‌کنید.`},{type:'code',text:i===0&&j===2?'print("سلام دنیا!")':`# نمونه‌ای از ${n}\nprint("با تمرین یاد می‌گیریم")`},{type:'tip',text:'نکته: کد را خودتان اجرا کنید و سپس مقدارها را تغییر دهید تا نتیجه را بهتر ببینید.'}],exercise:{prompt:`یک برنامه کوتاه بنویسید که مفهوم «${n}» را نشان دهد.`,starter:'# کد خود را اینجا بنویسید\n',expected:'print'},quiz:[{q:`کدام گزینه درباره «${n}» درست است؟`,choices:['پایتون یک زبان برنامه‌نویسی است','این مفهوم فقط در HTML وجود دارد','کدها هرگز اجرا نمی‌شوند'],answer:0},{q:'برای نمایش خروجی در پایتون از چه چیزی استفاده می‌کنیم؟',choices:['show()','print()','echo()'],answer:1},{q:'بهترین راه یادگیری برنامه‌نویسی چیست؟',choices:['فقط خواندن','تمرین و آزمایش','حفظ کردن همه کدها'],answer:1}]})));
const seed={users:[{username:'student',name:'نگار احمدی',role:'student',xp:180,streak:4,completed:[]},{username:'teacher',name:'سارا رضایی',role:'teacher'},{username:'admin',name:'مدیر سامانه',role:'admin'}],courses:[{id:'python101',title:'پایتون از پایه',description:'مسیر قدم‌به‌قدم یادگیری برنامه‌نویسی پایتون',modules:moduleLessons,published:true}],attempts:{},drafts:{},media:{},activity:{},user:null};
function load(){try{return {...seed,...JSON.parse(localStorage.getItem(STORE)||'{}')}}catch{return structuredClone(seed)}}let db=load();function save(){localStorage.setItem(STORE,JSON.stringify(db))}db.users=(db.users||[]).filter(u=>u&&u.username).map(u=>{delete u.password;return u});db.user=null;save();function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function who(){return db.users.find(u=>u.username===db.user)}function roleName(r){return {student:'دانش‌آموز',teacher:'مدرس',admin:'مدیر'}[r]||r}function totalLessons(){return db.courses[0].modules.reduce((a,m)=>a+m.length,0)}function allLessons(){return db.courses[0].modules.flat()}function percent(){let ids=new Set(allLessons().map(l=>l.id));return Math.round(((who()?.completed||[]).filter(id=>ids.has(id)).length/totalLessons())*100)}function go(page,args={}){location.hash=page+(args.id?`/${args.id}`:'')}function toast(s){let t=document.createElement('div');t.className='toast';t.textContent=s;document.body.append(t);setTimeout(()=>t.remove(),2800)}
function loginView(){window.scrollTo(0,0);document.getElementById('app').innerHTML=`<main class="neural-login"><div class="mercury-stage" aria-hidden="true"></div><section class="auth-panel"><div class="login-brand"><span class="brand-mark">N</span><span>Nova</span></div><div class="auth-kicker"><span class="kicker-dot"></span> ورود به فضای یادگیری</div><h1>خوش برگشتی</h1><p class="auth-lede">وارد حساب کاربری‌ات شو و یادگیری را ادامه بده.</p><form id="loginForm" autocomplete="on"><div class="neural-field"><label for="username"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="8" r="3.5"/><path d="M5 20c.8-3.5 3.1-5.2 7-5.2s6.2 1.7 7 5.2"/></svg> نام کاربری</label><input id="username" dir="ltr" autocomplete="username" required placeholder="نام کاربری"><i></i></div><div class="neural-field"><label for="password"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="10" width="14" height="10" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/></svg> گذرواژه</label><input id="password" type="password" dir="ltr" autocomplete="current-password" required placeholder="گذرواژه"><i></i></div><div id="loginError"></div><div class="submit-wrap"><span class="mercury-drop"></span><button class="btn-base" type="submit">ورود به حساب <span>←</span></button></div></form><div class="auth-foot"><span>حساب‌ها توسط مدیر سامانه ساخته می‌شوند</span><span class="demo-tag">Nova</span></div><p class="demo-storage">اطلاعات حساب با اتصال امن بررسی می‌شود.</p></section><aside class="login-aside"><div class="aside-topline"><span>آموزش برنامه‌نویسی</span><span>پایتون · سطح مقدماتی</span></div><div class="aside-illustration"><div class="book-tile"><svg viewBox="0 0 64 64" aria-hidden="true"><path d="M9 16c9-4 16-2 23 3v34c-7-5-14-7-23-3V16Z"/><path d="M55 16c-9-4-16-2-23 3v34c7-5 14-7 23-3V16Z"/><path d="M16 24c4-1 7 0 10 2M16 31c4-1 7 0 10 2M48 24c-4-1-7 0-10 2M48 31c-4-1-7 0-10 2"/><path d="m23 43 5 4 8-10"/></svg></div><span class="orbit-dot dot-one"></span><span class="orbit-dot dot-two"></span><span class="orbit-dot dot-three"></span></div><span class="brand-id">قدم‌به‌قدم، با تمرین واقعی</span><h2>یادگیری پایتون<br>از همین‌جا شروع می‌شود</h2><p>درس‌های کوتاه، تمرین‌های کاربردی و همراهی در مسیر یادگیری.</p><div class="aside-features"><div><span class="feature-icon">▤</span> درس‌های مرتب و مرحله‌ای</div><div><span class="feature-icon">&lt;/&gt;</span> تمرین و کدنویسی</div><div><span class="feature-icon">✓</span> پیگیری پیشرفت</div></div><div class="aside-footer"><span>Nova</span><span>فضای یادگیری پایتون</span></div></aside></main>`;document.getElementById('loginForm').onsubmit=async e=>{e.preventDefault();let form=e.currentTarget,button=form.querySelector('button[type="submit"]'),error=document.getElementById('loginError'),original=button.innerHTML;button.disabled=true;button.setAttribute('aria-busy','true');button.textContent='در حال ورود…';error.textContent='';try{let result=await api('/api/auth/login',{username:document.getElementById('username').value,password:document.getElementById('password').value},12000);let previous=db.users.find(u=>u.username===result.user.username)||{};delete previous.password;db.users=db.users.filter(u=>u.username!==result.user.username);db.users.push({...previous,username:result.user.username,name:result.user.name,role:result.user.role});db.user=result.user.username;save();go('dashboard')}catch(err){error.innerHTML=`<div class="auth-error">${esc(err.message||'ورود انجام نشد.')}</div>`;button.innerHTML=original;button.disabled=false;button.removeAttribute('aria-busy')}}}
const navByRole={student:[['dashboard','⌂','داشبورد'],['courses','▤','دوره‌ها'],['progress','◔','پیشرفت من'],['knowledge','◎','همزاد دانشی'],['tutor','✦','یار | دستیار هوشمند'],['profile','◎','پروفایل']],teacher:[['dashboard','⌂','داشبورد مدرس'],['manage','▤','مدیریت دوره'],['students','♙','دانش‌آموزان'],['reports','▥','گزارش‌ها'],['ai-studio','✦','استودیوی هوشمند']],admin:[['dashboard','⌂','داشبورد مدیر'],['users','♙','مدیریت کاربران'],['manage','▤','مدیریت دوره‌ها'],['reports','▥','گزارش‌ها']]};
function shell(page,content,title,sub=''){let u=who(),nav=navByRole[u.role];document.getElementById('app').innerHTML=`<div class="app-shell"><aside class="sidebar" id="sidebar"><div class="brand"><span class="brand-mark">N</span> Nova</div><div class="nav-label">منوی ${roleName(u.role)}</div><nav class="nav">${nav.map(([p,i,l])=>`<button class="${page===p?'active':''}" data-page="${p}"><span class="icon">${i}</span>${l}</button>`).join('')}</nav><div class="side-bottom"><div class="profile-mini"><div class="avatar">${esc(u.name[0])}</div><div>${esc(u.name)}<small>${roleName(u.role)}</small></div></div><div class="nav" style="width:100%;margin-top:10px"><button class="logout-link" onclick="logout()" style="width:100%;justify-content:flex-start"><span class="icon">↪</span>خروج</button></div></aside><main class="main"><header class="topbar"><div style="display:flex;gap:10px;align-items:center"><button class="icon-btn mobile-menu" onclick="document.getElementById('sidebar').classList.toggle('open')">☰</button><div><h1 class="page-title">${title}</h1><p class="subtitle">${sub}</p></div></div><div class="top-actions"><button class="btn soft help-trigger" type="button" onclick="showNovaGuide()">راهنما</button><span class="badge">نسخه نمایشی</span><span class="user-label">${esc(u.name)}</span><div class="avatar">${esc(u.name[0])}</div></div></header>${content}<p class="footer-note">Nova · دموی آموزشی — اطلاعات در مرورگر شما ذخیره می‌شود</p></main></div>`;document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page))}
const novaPageGuides={student:[['داشبورد','ادامه درس، امتیاز تجربه، زنجیره یادگیری و پیشنهادهای مرور را می‌بینی. اعداد و نمودارهای برچسب‌خورده به‌عنوان نمونه، داده زنده نیستند.'],['دوره‌ها','دوره پایتون از پایه را باز کن و فصل‌ها را به ترتیب جلو برو. انتخاب یک دوره در این نمونه، ثبت‌نام نمایشی است.'],['درس','مطالب درس را بخوان، ویدیوی تأییدشده را ببین، تمرین را در محیط ساده‌شده بررسی کن و آزمون کوتاه را پاسخ بده. اجرای تمرین، مفسر واقعی پایتون نیست.'],['پیشرفت من','امتیازها و درس‌های تکمیل‌شده را مرور کن. تا اتصال و تکمیل backend، بخشی از این صفحه از داده نمونه یا ذخیره مرورگر استفاده می‌کند.'],['یار آموزشی','از یار درباره درس جاری، مفهوم پایتون یا کد سؤال کن. پاسخ AI به اتصال OpenRouter و محتوای درس/راهنمای مدرس نیاز دارد. فایل انتخابی در نمونه فقط نامش را نشان می‌دهد و بارگذاری نمی‌شود.'],['پروفایل','امتیاز تجربه، سطح و دستاوردهای نمایشی خود را ببین.']],teacher:[['داشبورد مدرس','نمای کلی کلاس، زمان مطالعه و نتیجه آزمون‌ها را بررسی کن. گزارش‌های زنده فقط پس از ثبت داده در PostgreSQL در دسترس‌اند.'],['مدیریت دوره','محتوای دوره و بلوک‌های درس را ویرایش کن؛ تمرین، آزمون و ویدیو را به درس مرتبط کن. رسانه باید بعد از بارگذاری و بازبینی منتشر شود.'],['دانش‌آموزان','فعالیت و پیشرفت دانش‌آموزان را دنبال کن. آمار نمونه را با گزارش زنده پایگاه داده اشتباه نگیر.'],['گزارش‌ها','نتایج آزمون و روند یادگیری را مرور کن؛ برای گزارش واقعی باید آزمون‌های منتشرشده و تلاش‌های دانش‌آموز در backend ثبت شوند.'],['استودیوی هوشمند','موضوع و سطح را انتخاب کن، راهنمای تدریس و منبع تأییدشده بده، سپس پیش‌نویس AI را بازبینی و اصلاح کن. AI نباید خودکار درس را منتشر کند.']],admin:[['داشبورد مدیر','وضعیت کلی و میانبرهای مدیریت را می‌بینی؛ شاخص‌های نمایشی را با آمار واقعی اشتباه نگیر.'],['مدیریت کاربران','در دمو فهرست حساب‌ها نمونه‌ای است. برای کاربران واقعی، ایجاد حساب، تغییر نقش و بازیابی گذرواژه باید از endpointهای امن و پایگاه داده انجام شود.'],['مدیریت دوره‌ها','محتوای دوره و رسانه‌ها را بررسی کن. انتشار ویدیوی بارگذاری‌شده باید پس از بازبینی مدیر باشد.'],['گزارش‌ها','آمار پلتفرم را مرور کن. گزارش واقعی به داده‌های ذخیره‌شده و اتصال پایگاه داده نیاز دارد.']]};
function showNovaGuide(){const role=who()?.role||'student',page=location.hash.replace(/^#\/?/,'').split('/')[0]||'dashboard',labels={dashboard:'داشبورد',courses:'دوره‌ها',course:'دوره‌ها',lesson:'درس',progress:'پیشرفت من',tutor:'یار آموزشی',profile:'پروفایل',manage:'مدیریت دوره',students:'دانش‌آموزان',reports:'گزارش‌ها','ai-studio':'استودیوی هوشمند',users:'مدیریت کاربران'},currentTitle=labels[page]||'راهنمای استفاده',items=novaPageGuides[role]||[];const modal=document.createElement('div');modal.className='nova-guide-backdrop';modal.innerHTML=`<section class="nova-guide-card" role="dialog" aria-modal="true" aria-labelledby="novaGuideTitle"><button class="nova-guide-close" type="button" aria-label="بستن راهنما">×</button><span class="section-eyebrow">راهنمای همیشگی Nova · ${esc(roleName(role))}</span><h2 id="novaGuideTitle">${esc(currentTitle)}</h2><p class="nova-guide-intro">هر زمان لازم داشتی، این راهنما را از بالای صفحه باز کن. بخش‌های زیر برای نقش فعلی تو هستند.</p><div class="nova-guide-list">${items.map(([title,description])=>`<details ${title===currentTitle?'open':''}><summary>${esc(title)}</summary><p>${esc(description)}</p></details>`).join('')}</div><details class="nova-guide-config"><summary>نسخه دمو و تنظیمات سامانه</summary><p>نسخه محلی برای نمایش است؛ از آن برای نگهداری اطلاعات واقعی دانش‌آموزان استفاده نکن. مدیر فنی باید کلیدها را فقط در تنظیمات محرمانه میزبان ثبت کند: DATABASE_URL، DATABASE_SSL، OPENROUTER_API_KEY و متغیرهای CLOUDINARY. پس از اتصال پایگاه داده، مهاجرت جداول و ساخت حساب مدیر اولیه لازم است. هرگز رمزها را در کد مرورگر یا پیام عمومی قرار نده.</p></details><p class="nova-guide-note">یادآوری: بعضی قابلیت‌ها هنوز نمایشی‌اند و تا اتصال پایگاه داده و تکمیل backend ماندگار نمی‌شوند.</p></section>`;document.body.append(modal);const close=()=>modal.remove();modal.querySelector('.nova-guide-close').onclick=close;modal.addEventListener('click',event=>{if(event.target===modal)close()});const onKey=event=>{if(event.key==='Escape'){close();document.removeEventListener('keydown',onKey)}};document.addEventListener('keydown',onKey)}
function stat(label,value,note,icon){return `<article class="card"><span class="stat-icon">${icon}</span><div class="stat-label">${label}</div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></article>`}
function courseCard(){return `<article class="card course-card"><div class="course-art">🐍</div><div class="course-info"><span class="badge green">دوره فعال</span><h3>پایتون از پایه</h3><div class="muted">۱۰ فصل · ۲۷ درس · مناسب شروع</div><div class="progress"><span style="width:${percent()}%"></span></div><div class="row muted"><small>${percent()}٪ تکمیل شده</small><button class="btn soft" onclick="go('course')">ادامه یادگیری ←</button></div></div></article>`}
function bars(){let vals=[48,65,57,76,68,88,73],labs=['ش','ی','د','س','چ','پ','ج'];return `<div class="bar-chart" role="img" aria-label="نمودار نمونه امتیازهای هفتگی">${vals.map((v,i)=>`<div class="bar-col"><div class="bar" style="height:${v}%" title="${v} از ۱۰۰"></div><small>${labs[i]}</small></div>`).join('')}</div><div class="chart-legend">میانگین امتیاز آزمون‌ها در ۷ روز اخیر · داده نمایشی</div>`}
function dashboard(){let u=who();if(u.role==='student')return shell('dashboard',`<section class="welcome-hero"><div><span class="hero-eyebrow">مسیر یادگیری تو</span><h2>سلام ${esc(u.name)}،<br>آماده‌ای یک قدم جلوتر بروی؟</h2><p>${activeCourse().subject==='english'?'هر تمرین کوتاه، تو را به مکالمه‌ای روان‌تر نزدیک می‌کند.':'ادامه بده؛ هر تمرین تو را به برنامه‌نویس بهتری تبدیل می‌کند.'}</p><button class="btn hero-button" onclick="go('lesson',{id:'${allLessons().find(l=>!u.completed.includes(l.id))?.id||allLessons()[0].id}'})">شروع درس بعدی <span>←</span></button></div><div class="hero-art"><div class="hero-orbit orbit-one"></div><div class="hero-orbit orbit-two"></div><div class="hero-python">🐍</div><div class="floating-code">print("سلام دنیا!")</div></div></section><section class="grid stats">${stat('امتیاز تجربه',u.xp||0,'ادامه بده؛ عالی پیش می‌روی','✦')}${stat('سطح',Math.floor((u.xp||0)/100)+1,'سطح یادگیرنده','↗')}${stat('زنجیره روزانه',`${u.streak||0} روز`,'تمرین روزانه را حفظ کن','🔥')}${stat('پیشرفت دوره',`${percent()}٪`,'از ${totalLessons()} درس دوره','◔')}</section>${activeCourse().subject==='english'?englishVideoCard():studentVideoCard()}<section class="grid two"><div>${courseCard()}<div class="section"><div class="row"><h2>ادامه مسیر</h2><span class="muted">درس‌های پیشنهادی</span></div><div class="card">${lessonList(allLessons().slice(0,5))}<button class="btn soft" onclick="go('course')">دیدن همه درس‌ها</button></div></div></div><div><article class="card"><h2 class="card-title">نتیجه آزمون‌ها <span class="badge">۷ روز اخیر</span></h2>${bars()}</article><article class="card section"><h2 class="card-title">موضوع‌های نیازمند مرور</h2><span class="badge amber">حلقه‌ها</span> <span class="badge amber">توابع</span><p class="muted">این پیشنهاد نمونه است و با ثبت پاسخ‌های شما کامل‌تر می‌شود.</p></article><article class="card section tutor-teaser" onclick="go('tutor')"><div class="ai-icon">✦</div><div><b>از یار سوال بپرس</b><p class="muted">راهنمای درس و پایتون</p></div><span class="badge amber">آماده اتصال</span></article></div></section>`,`داشبورد`,`مسیر یادگیری پایتون`);if(u.role==='teacher')return teacherDashboard();let label='داشبورد مدیر';return shell('dashboard',`<section class="welcome-hero compact-hero"><div><span class="hero-eyebrow">نمای کلی پلتفرم</span><h2>${label}، ${esc(u.name)}</h2><p>مدیریت محتوا، بررسی پیشرفت و ادامه ساخت تجربه یادگیری.</p><button class="btn hero-button" onclick="go('manage')">رفتن به مدیریت محتوا <span>←</span></button></div><div class="hero-art"><div class="hero-orbit orbit-one"></div><div class="hero-orbit orbit-two"></div><div class="hero-python">✎</div></div></section><section class="grid stats">${stat('دوره‌های فعال',1,'یک دوره نمایشی','▤')}${stat('دانش‌آموزان',db.users.filter(x=>x.role==='student').length,'حساب‌های نمونه','♙')}${stat('درس‌های دوره',totalLessons(),'قابل ویرایش در دمو','▣')}${stat('وضعیت AI','متصل نیست','پس از دریافت API تنظیم می‌شود','✦')}</section>${c.subject==='english'?englishVideoCard():studentVideoCard()}<section class="grid two"><div>${courseCard()}<div class="section"><h2>میانبرها</h2><div class="card"><button class="btn primary" onclick="go('manage')">مدیریت محتوا</button> <button class="btn" onclick="go('reports')">مشاهده گزارش‌ها</button> ${u.role==='admin'?'<button class="btn" onclick="go(\'users\')">مدیریت کاربران</button>':''}</div></div></div><article class="card"><h2 class="card-title">نشانه‌های فعالیت</h2>${bars()}<p class="muted">گزارش نمایشی؛ با تلاش‌های واقعی دانش‌آموزان به‌روزرسانی می‌شود.</p></article></section>`,label,'نمای کلی سامانه در نسخه نمایشی')}
function lessonList(lessons){return lessons.map(l=>`<div class="lesson-row"><span class="lesson-num ${who().completed?.includes(l.id)?'done':''}">${who().completed?.includes(l.id)?'✓':l.module}</span><div class="lesson-desc"><b>${esc(l.name)}</b><div class="muted" style="font-size:11px">فصل ${l.module} · آزمون و تمرین</div></div><button class="btn" onclick="go('lesson',{id:'${l.id}'})">${who().completed?.includes(l.id)?'مرور':'شروع'} ←</button></div>`).join('')}
function coursePage(){let groups=db.courses[0].modules;return shell('courses',`<div class="notice">دوره نمونه آموزشی · ${totalLessons()} درس · پیشرفت شما ${percent()}٪</div>${groups.map((g,i)=>`<details class="module" ${i===0?'open':''}><summary>فصل ${i+1}: ${esc(moduleNames[i])} <span class="badge">${g.filter(x=>who().completed?.includes(x.id)).length}/${g.length} درس</span></summary><div class="module-lessons">${lessonList(g)}</div></details>`).join('')}`,'دوره پایتون از پایه','از فصل اول شروع کن و قدم‌به‌قدم جلو برو.')}
function coursesPage(){return shell('courses',`<section class="grid three">${courseCard()}<article class="card"><div class="course-art">🧩</div><h3>تمرین‌های پایتون</h3><p class="muted">تمرین‌های کوتاه برای تثبیت مفاهیم.</p><span class="badge amber">محتوای دمو</span></article></section>`,'دوره‌ها','مسیر یادگیری خودت را انتخاب کن.')}
function lessonPage(id){let l=allLessons().find(x=>x.id===id)||allLessons()[0],u=who(),lessonVideos=Object.values(db.media||{}).filter(m=>m.status==='approved'&&m.lessonId===l.id);db.currentLessonId=l.id;save();let blocks=l.blocks.map(b=>blockHtml(b)).join('');let html=`<div class="row"><div class="muted">فصل ${l.module} از ۱۰ · ${esc(l.name)}</div><button class="btn" onclick="go('course')">بازگشت به دوره</button></div>${blocks?`<div class="section">${blocks}</div>`:''}${lessonVideos.length?`<section class="lesson-video-library"><h2>ویدیوهای این درس</h2>${lessonVideos.map(m=>`<article class="card lesson-video-item"><video controls playsinline preload="metadata" src="${esc(m.secureUrl)}"></video><h3>${esc(m.title||m.filename)}</h3></article>`).join('')}</section>`:''}<div class="section"><article class="card"><h2 class="card-title">تمرین کدنویسی <span class="badge">محیط محدود نمایشی</span></h2><p>${esc(l.exercise.prompt)}</p><textarea id="exerciseCode" class="textarea code" dir="ltr">${esc(l.exercise.starter)}</textarea><div id="exerciseResult" class="notice">این محیط اجرای کامل پایتون نیست؛ بررسی تمرین در نسخه دمو ساده‌سازی شده است.</div><button class="btn primary" onclick="runExercise('${l.id}')">بررسی پاسخ</button></article></div><div class="section"><article class="card"><h2 class="card-title">آزمون کوتاه</h2><form id="quizForm">${l.quiz.map((q,i)=>`<div class="question">${i+1}. ${esc(q.q)}</div>${q.choices.map((c,j)=>`<label class="choice"><input type="radio" name="q${i}" value="${j}" required>${esc(c)}</label>`).join('')}`).join('')}<button class="btn primary">ثبت پاسخ‌ها</button><span id="quizResult"></span></form></article></div><div class="section"><article class="card"><div class="row"><div><h2 class="card-title" style="margin:0">پرسش از یار</h2><small class="muted">راهنمای هوشمند درس</small></div><button class="btn soft" onclick="go('tutor',{id:'${l.id}'})">باز کردن پنل</button></div><div class="notice">درباره همین درس از یار بپرس؛ نام درس و محتوای تأییدشده همراه پرسشت ارسال می‌شود.</div></article></div><div class="section"><button class="btn primary" onclick="completeLesson('${l.id}')">${u.completed?.includes(l.id)?'درس تکمیل شده ✓':'علامت‌گذاری به‌عنوان تکمیل‌شده · +20 XP'}</button></div>`;shell('courses',html,l.name,'یادگیری با مطالعه، تمرین و آزمون')}
function blockHtml(b){if(b.type==='heading')return `<div class="block"><h2>${esc(b.text)}</h2></div>`;if(b.type==='code')return `<pre class="code">${esc(b.text)}</pre>`;if(b.type==='tip')return `<div class="block tip">💡 ${esc(b.text)}</div>`;return `<div class="block">${esc(b.text)}</div>`}
function completeLesson(id){let u=who();u.completed=u.completed||[];if(!u.completed.includes(id)){u.completed.push(id);u.xp=(u.xp||0)+20;save();toast('درس تکمیل شد؛ ۲۰ امتیاز گرفتی!')}else toast('این درس قبلاً تکمیل شده است.');route()}
function runExercise(id){let code=document.getElementById('exerciseCode').value;let ok=/print\s*\(/.test(code)||code.trim().length>18;let out=document.getElementById('exerciseResult');if(ok){let u=who();u.completed=u.completed||[];let key=`exercise-${id}`;if(!u.completed.includes(key)){u.completed.push(key);u.xp=(u.xp||0)+10;save()}out.className='notice';out.innerHTML='آفرین! پاسخ در بررسی ساده دمو پذیرفته شد. <span class="badge green">+۱۰ XP</span>'}else{out.className='notice';out.textContent='کد را کامل‌تر کن و دوباره تلاش کن.'}}
async function submitQuiz(e,id){e.preventDefault();let l=allLessons().find(x=>x.id===id),fd=new FormData(e.target),answers=l.quiz.map((_,i)=>Number(fd.get(`q${i}`))),button=e.target.querySelector('button[type="submit"]'),resultNode=document.getElementById('quizResult');button.disabled=true;try{const result=await api('/api/activity/quiz',{lessonKey:id,answers});const pct=Number(result.score);db.attempts[who().username]=db.attempts[who().username]||[];db.attempts[who().username].push({lesson:id,score:pct,date:result.createdAt});if(result.passed){let u=who(),key=`quiz-${id}`;u.completed=u.completed||[];if(!u.completed.includes(key)){u.completed.push(key);u.xp=(u.xp||0)+15}}save();resultNode.innerHTML=`<span class="badge ${pct>=60?'green':'amber'}">نتیجه ثبت شد: ${pct}٪ · ${result.correct} از ${result.total}</span>`}catch(err){resultNode.innerHTML=`<span class="badge amber">نتیجه ذخیره نشد: ${esc(err.message)}. آزمون باید ابتدا در پایگاه داده منتشر شود.</span>`}finally{button.disabled=false}}
function progressPage(){const username=who().username,a=db.attempts[username]||[],avg=a.length?Math.round(a.reduce((s,x)=>s+x.score,0)/a.length):0,c=activeCourse(),english=c.subject==='english',topics=english?['واژگان روزمره','گرامر در گفتگو','مکالمه و شنیدن']:['حلقه‌ها','توابع','متغیرها'];return shell('progress',`<section class="course-switcher-notice">پیشرفت در دوره <b>${esc(c.title)}</b></section><section class="grid stats">${stat('پیشرفت دوره',`${percent()}٪`,'درس‌های تکمیل‌شده','◔')}${stat('میانگین آزمون',`${avg}٪`,'بر اساس تلاش‌های این مرورگر','▥')}${stat('آزمون‌های ثبت‌شده',a.length,'ادامه تمرین','✓')}${stat('امتیاز تجربه',who().xp||0,'مجموع XP','✦')}</section><section class="grid two"><article class="card"><h2 class="card-title">نتایج آزمون‌ها · ${esc(c.title)}</h2>${bars()}<p class="muted">نمودار نمونه تا ثبت پاسخ‌های کافی. جزئیات آزمون‌ها در این نسخه در همین مرورگر می‌مانند.</p></article><article class="card"><h2 class="card-title">${english?'مهارت‌های پیشنهادی برای تمرین':'موضوع‌های پیشنهادی برای مرور'}</h2>${topics.map((t,i)=>`<div class="list-row">${esc(t)} <span class="badge ${i===2?'green':'amber'}">${i===2?'در مسیر خوب':'تمرین بیشتر'}</span></div>`).join('')}<button class="btn primary" onclick="go('knowledge')">دیدن همزاد دانشی و بررسی کاربرد مفاهیم</button></article></section>`,'پیشرفت من',c.title)}
function knowledgePage(){const username=who().username,saved=(db.knowledgeTwin||{})[username]||{},lessons=allLessons(),selected=lessons.find(l=>l.id===(db.currentLessonId||''))||lessons.find(l=>!(who().completed||[]).includes(l.id))||lessons[0],latest=saved[selected.id]||Object.values(saved).at(-1),attempts=db.attempts[username]||[],evidence=attempts.map(a=>{let l=lessons.find(x=>x.id===a.lesson);return l?`${l.name}: quiz score ${a.score}%`:''}).filter(Boolean).slice(-8).join('\n')||'هنوز نتیجه آزمون ثبت‌شده‌ای در این مرورگر نیست.';const dimensionRows=latest?.dimensions||[];return shell('knowledge',`<section class="knowledge-hero"><div><span class="hero-eyebrow">مدل زنده یادگیری تو</span><h2>همزاد دانشی</h2><p>فقط جواب درست را نمی‌سنجیم؛ بررسی می‌کنیم مفهوم را چطور توضیح می‌دهی و آیا می‌توانی آن را در موقعیت تازه به کار ببری.</p></div><div class="knowledge-mark">◎</div></section><div class="notice knowledge-caveat"><b>یک برآورد موقت، نه نمره یا تشخیص قطعی.</b> هر بُعد فقط از شواهد موجود تخمین زده می‌شود. پاسخ‌ها در این نسخه نمایشی در همین مرورگر می‌مانند و با شواهد تازه تغییر می‌کنند.</div><section class="grid two knowledge-layout"><article class="card"><h2 class="card-title">یک نمونه از دانسته‌هایت نشان بده</h2><p class="muted">برای سنجیدن انتقال یادگیری، مفهوم را در مثالی تازه به کار ببر. می‌توانی فارسی، انگلیسی یا ترکیبی بنویسی. متن برای ارزیابی به OpenRouter فرستاده می‌شود؛ اطلاعات شخصی ننویس.</p><label for="twinLesson">درس و مفهوم</label><select id="twinLesson" class="select">${lessons.map(l=>`<option value="${esc(l.id)}" ${l.id===selected.id?'selected':''}>فصل ${l.module} · ${esc(l.name)}</option>`).join('')}</select><label for="twinExplain">مفهوم را با زبان خودت توضیح بده</label><textarea id="twinExplain" class="textarea" maxlength="3000" placeholder="فکر می‌کنی این مفهوم چه کاری انجام می‌دهد؟ چرا؟"></textarea><label for="twinTransfer">یک کاربرد در موقعیت جدید</label><textarea id="twinTransfer" class="textarea" maxlength="3000" placeholder="مثلاً: چطور می‌توانی همین مفهوم را در برنامه‌ای متفاوت به کار ببری؟"></textarea><label for="twinConfidence">چقدر به پاسخ خودت مطمئنی؟ <span id="twinConfidenceText">۳ از ۵</span></label><input id="twinConfidence" type="range" min="1" max="5" value="3" class="twin-range"><button id="twinSubmit" class="btn primary">به‌روزرسانی همزاد دانشی</button><div id="twinStatus" class="muted" role="status"></div></article><aside class="card"><h2 class="card-title">شواهد یادگیری در این مرورگر</h2><p class="muted">نتیجه آزمون‌ها کمک می‌کند، اما به‌تنهایی نشان‌دهنده فهم یا توانایی کاربرد نیست.</p><div class="evidence-list">${evidence.split('\n').map(x=>`<div class="list-row">${esc(x)}</div>`).join('')}</div><div class="notice">پاسخ تشریحی، انتقال به موقعیت جدید و اعتمادبه‌نفس خودت هم در کنار آزمون بررسی می‌شوند.</div></aside></section>${latest?`<section class="card twin-results"><div class="row"><div><span class="section-eyebrow">بر اساس شواهد فعلی</span><h2 class="card-title">نمای دانشی · ${esc(lessons.find(l=>l.id===latest.lessonId)?.name||selected.name)}</h2></div><span class="badge amber">برآورد شواهد</span></div><p class="twin-summary-copy">${esc(latest.summary||'این برآورد با شواهد تازه به‌روز می‌شود.')}</p><div class="twin-dimensions">${dimensionRows.map(d=>`<div class="twin-dimension"><div class="row"><b>${esc(d.label||twinDimensions.find(x=>x[0]===d.key)?.[1]||d.key)}</b><strong>${d.estimate===null?'شواهد کافی نیست':`نشانه‌ها: ${d.estimate} از ۱۰۰`}</strong></div>${d.estimate===null?'<div class="twin-unknown">برای این بُعد هنوز شواهد کافی نداریم.</div>':`<div class="twin-track"><i style="width:${Math.max(0,Math.min(100,Number(d.estimate)||0))}%"></i></div>`}<small>${esc(d.evidence||'')}</small></div>`).join('')}</div><p class="twin-scale-note">این عددها نشانه‌های موقت از شواهد فعلی‌اند، نه نمره آزمون یا درجه‌بندی ثابت.</p>${latest.misconceptions?.length?`<h3>نکته‌هایی برای روشن‌کردن</h3><ul>${latest.misconceptions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}<div class="notice"><b>گام بعدی:</b> ${esc(latest.next_step||'یک مسئله تازه را امتحان کن.')}</div></section>`:''}`,'همزاد دانشی','فهم، شواهد، کاربرد و رشد');const range=document.getElementById('twinConfidence');range.oninput=()=>document.getElementById('twinConfidenceText').textContent=`${range.value} از ۵`;document.getElementById('twinSubmit').onclick=async()=>{const explanation=document.getElementById('twinExplain').value.trim(),transfer=document.getElementById('twinTransfer').value.trim(),lessonId=document.getElementById('twinLesson').value,lesson=lessons.find(l=>l.id===lessonId)||selected,status=document.getElementById('twinStatus'),button=document.getElementById('twinSubmit');if(!explanation&&!transfer){status.textContent='برای ادامه، یک توضیح یا نمونه کاربردی بنویس.';return}button.disabled=true;status.textContent='یار شواهد را بررسی می‌کند…';try{const quizEvidence=(db.attempts[username]||[]).filter(a=>a.lesson===lessonId).map(a=>`Quiz result: ${a.score}%`).join('; ')||'No quiz attempt recorded for this lesson';const result=await api('/api/ai',{mode:'knowledge_twin',concept:lesson.name,courseTitle:activeCourse().title,subject:activeCourse().subject||'python',targetLanguage:activeCourse().targetLanguage||'',instructionLanguage:activeCourse().instructionLanguage||'Persian',chapterNumber:lesson.module,lessonTitle:lesson.name,explanation,transfer,confidence:range.value,evidence:quizEvidence,lessonContent:lesson.blocks.map(b=>'['+b.type+'] '+b.text).join('\n'),teacherGuidance:[db.aiKnowledge?.guidanceByLesson?.[lessonId]||'',...(db.aiKnowledge?.approvedSourcesByLesson?.[lessonId]||[]).filter(s=>s.approved).map(s=>'منبع تأییدشده: '+s.title+'\\n'+s.content)].filter(Boolean).join('\\n\\n'),role:'student'});const twin=result.answer?.twin;if(!twin?.dimensions)throw new Error('ارزیابی یادگیری ناقص بود. دوباره تلاش کن.');db.knowledgeTwin=db.knowledgeTwin||{};db.knowledgeTwin[username]=db.knowledgeTwin[username]||{};const updatedAt=new Date().toISOString(),previous=db.knowledgeTwin[username][lessonId]||{},observation={...twin,lessonId,updatedAt};db.knowledgeTwin[username][lessonId]={...observation,history:[...(previous.history||[]),{summary:twin.summary,dimensions:twin.dimensions,updatedAt}].slice(-20)};save();knowledgePage()}catch(err){status.textContent=err.message}finally{button.disabled=false}}}
function renderTutorAnswer(text){const lines=String(text||'').split(/\r?\n/).filter(line=>!/^\s*Progress:\s*/i.test(line));let html='',inCode=false,codeLines=[],inList=false;const inline=s=>esc(s).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>');const closeList=()=>{if(inList){html+='</ul>';inList=false}};for(const line of lines){if(/^\s*```/.test(line)){closeList();if(inCode){html+='<pre class="tutor-code"><code>'+esc(codeLines.join('\n'))+'</code></pre>';codeLines=[];inCode=false}else inCode=true;continue}if(inCode){codeLines.push(line);continue}let t=line.trim();if(!t){closeList();continue}if(/^[-*]\s+/.test(t)){if(!inList){html+='<ul>';inList=true}html+='<li>'+inline(t.replace(/^[-*]\s+/,''))+'</li>';continue}closeList();if(/^#{1,3}\s+/.test(t)){html+='<h4>'+inline(t.replace(/^#{1,3}\s+/,''))+'</h4>';continue}html+='<p>'+inline(t)+'</p>'}closeList();if(inCode)html+='<pre class="tutor-code"><code>'+esc(codeLines.join('\n'))+'</code></pre>';return html}
function tutorPage(lessonId){let msgs=window.tutorMessages||[],files=window.aiFiles||[],category=window.aiCategory||null,suggestions={learn:['این مفهوم را با زبان ساده توضیح بده','فرق متغیر و مقدار چیست؟','نکته‌های مهم این درس را مرور کن','برای یادگیری این مبحث راهنمایی‌ام کن'],code:['این خطای پایتون را توضیح بده','کد من را قدم‌به‌قدم بررسی کن','برای این تمرین فقط یک سرنخ بده','یک مثال کوتاه درباره حلقه‌ها بزن'],practice:['برای این درس یک تمرین پیشنهاد بده','از من یک سوال کوتاه بپرس','کمکم کن جوابم را خودم پیدا کنم','اشتباه رایج در این مبحث چیست؟']};let available=allLessons().filter(l=>!db.drafts?.[l.id]),current=available.find(l=>l.id===lessonId)||available.find(l=>l.id===db.currentLessonId)||available.find(l=>!(who().completed||[]).includes(l.id))||available[0]||allLessons()[0];shell('tutor',`<section class="assistant-page"><div class="assistant-brand"><div class="assistant-logo"><span></span><span></span><span></span></div><span id="aiStatus" class="badge"><i class="status-dot"></i> دستیار هوشمند</span></div><header class="assistant-welcome"><span class="assistant-kicker">یار · همراه یادگیری پایتون</span><h2>سلام ${esc(who().name)}،<br><em>چه چیزی را یاد بگیریم؟</em></h2><p>درباره درس فعلی بپرس، کدت را مرور کن یا برای تمرین یک راهنمایی بگیر.</p><div class="lesson-chip"><span>درس فعلی</span><b>${esc(current.name)}</b><button onclick="go('lesson',{id:'${current.id}'})">رفتن به درس</button></div></header><div class="assistant-composer-card"><form id="assistantForm"><textarea id="assistantInput" rows="3" placeholder="مثلاً: حلقه for را با یک مثال توضیح بده…" aria-label="پرسش برای یار">${esc(window.aiDraft||'')}</textarea><div class="selected-files">${files.map((f,i)=>`<span class="file-chip">▤ ${esc(f)} <button type="button" aria-label="حذف فایل" onclick="removeAiFile(${i})">×</button></span>`).join('')}</div><div class="composer-divider"></div><div class="composer-actions"><div class="composer-modes"><button type="button" class="mode-toggle ${window.aiSearch?'mode-on':''}" onclick="toggleAiOption('aiSearch')">⌕ <span>جست‌وجو</span><small>آماده اتصال</small></button><button type="button" class="mode-toggle ${window.aiReason?'mode-on':''}" onclick="toggleAiOption('aiReason')">✧ <span>تحلیل</span><small>آماده اتصال</small></button></div><div class="composer-send-group"><button type="button" class="attach-button" onclick="document.getElementById('aiFileInput').click()">＋ <span>افزودن فایل</span></button><input id="aiFileInput" type="file" hidden accept=".pdf,.txt,.py,.md,image/*"><button class="assistant-send" aria-label="ارسال">↑</button></div></div></form><p class="upload-hint">فایل‌ها فعلاً فقط به‌عنوان مرجع نام‌گذاری می‌شوند و به مدل فرستاده نمی‌شوند.</p></div>${msgs.length?`<div class="assistant-thread">${msgs.map(m=>`<div class="thread-user">${esc(m.question)}</div><div class="thread-offline"><span class="assistant-mini-logo">✦</span><div><b>${m.answer?'پاسخ یار':m.error?'خطا':'در حال پاسخ'}</b><div class="tutor-answer">${m.answer?renderTutorAnswer(m.answer):`<p>${esc(m.error||'در حال دریافت پاسخ…')}</p>`}</div></div></div>`).join('')}</div>`:''}<div class="command-tabs"><button class="command-tab ${category==='learn'?'active':''}" onclick="setAiCategory('learn')"><span>▤</span> یادگیری</button><button class="command-tab ${category==='code'?'active':''}" onclick="setAiCategory('code')"><span>&lt;/&gt;</span> کدنویسی</button><button class="command-tab ${category==='practice'?'active':''}" onclick="setAiCategory('practice')"><span>✎</span> تمرین</button></div>${category?`<section class="suggestion-panel"><div class="suggestion-head"><div><span class="assistant-kicker">پیشنهادهای آماده</span><h3>${category==='learn'?'یادگیری مفاهیم':category==='code'?'کمک در کدنویسی':'تمرین و مرور'}</h3></div><button class="small-btn" onclick="setAiCategory(null)">بستن ×</button></div><div class="suggestion-list">${suggestions[category].map((s,i)=>`<button class="suggestion-item" onclick="useAiSuggestion(${i})"><span class="suggestion-icon">${category==='code'?'&lt;/&gt;':category==='practice'?'✎':'✧'}</span><span>${s}</span><b>←</b></button>`).join('')}</div></section>`:''}<div class="assistant-footnote">یار بر اساس درس و راهنمای مدرس کمک می‌کند؛ هنگام آزمون، به‌جای پاسخ نهایی سرنخ می‌دهد.</div></section>`,'یار','فضایی برای پرسیدن، فهمیدن و تمرین کردن');let form=document.getElementById('assistantForm'),input=document.getElementById('assistantInput');input.oninput=()=>window.aiDraft=input.value;form.onsubmit=async e=>{e.preventDefault();let text=input.value.trim();if(!text)return;window.tutorMessages=window.tutorMessages||[];window.tutorMessages.push({question:text});window.aiDraft='';tutorPage();try{let currentMessage=window.tutorMessages.at(-1);let knowledge=db.aiKnowledge||{},guidance=knowledge.guidanceByLesson?.[current.id]||'',sources=knowledge.approvedSourcesByLesson?.[current.id]||[],lessonText=[`Lesson: ${current.name}`,`Chapter: ${current.module}`,`Lesson blocks:\n${current.blocks.map(b=>`[${b.type}] ${b.text}`).join('\n')}`,`Exercise: ${current.exercise?.prompt||''}`,`Starter code: ${current.exercise?.starter||''}`,`Quiz questions (without answer keys):\n${(current.quiz||[]).map(q=>`${q.q}\n${(q.choices||[]).join(' | ')}`).join('\n')}`].join('\n\n');let approvedText=sources.filter(x=>x.approved).map(x=>`${x.title}: ${x.content}`).join('\n\n');let result=await api('/api/ai',{mode:'tutor',role:'student',message:text,chapterNumber:current.module,chapterOutline:moduleNames.map((name,index)=>`${index+1}. ${name}`).join('\n'),lessonTitle:current.name,lessonContent:lessonText,teacherGuidance:[guidance,approvedText?`Approved teacher sources for this lesson:\n${approvedText}`:''].filter(Boolean).join('\n\n')});currentMessage.answer=result.answer}catch(err){window.tutorMessages.at(-1).error=err.message;window.aiDraft=text}tutorPage()};document.getElementById('aiFileInput').onchange=e=>{let selected=[...e.target.files].map(f=>f.name);window.aiFiles=[...(window.aiFiles||[]),...selected];tutorPage()}}
function setAiCategory(category){window.aiCategory=window.aiCategory===category?null:category;tutorPage()}function toggleAiOption(key){window[key]=!window[key];tutorPage()}function removeAiFile(i){window.aiFiles.splice(i,1);tutorPage()}function useAiSuggestion(i){let cat=window.aiCategory||'learn';let suggestions={learn:['این مفهوم را با زبان ساده توضیح بده','فرق متغیر و مقدار چیست؟','نکته‌های مهم این درس را مرور کن','برای یادگیری این مبحث راهنمایی‌ام کن'],code:['این خطای پایتون را توضیح بده','کد من را قدم‌به‌قدم بررسی کن','برای این تمرین فقط یک سرنخ بده','یک مثال کوتاه درباره حلقه‌ها بزن'],practice:['برای این درس یک تمرین پیشنهاد بده','از من یک سوال کوتاه بپرس','کمکم کن جوابم را خودم پیدا کنم','اشتباه رایج در این مبحث چیست؟']};window.aiDraft=suggestions[cat][i]||'';tutorPage();document.getElementById('assistantInput').focus()}
function selectTutorMode(i){let input=document.getElementById('chatInput');if(!input)return;let starters=['لطفاً این مفهوم را توضیح بده: ','این موضوع را ساده‌تر توضیح بده: ','برای این تمرین یک سرنخ بده: ','این خطای کد را بررسی کن: ','یک مثال درباره این موضوع توضیح بده: ','نکته‌های مهم این درس را مرور کن: ','برای آزمون این بخش کمکم کن: ','یک تمرین برایم پیشنهاد کن: '];input.value=starters[i]+(allLessons().find(l=>!(who().completed||[]).includes(l.id))?.name||'پایتون');input.focus()}
function profilePage(){let u=who();return shell('profile',`<section class="grid two"><article class="card"><div class="row"><div class="avatar" style="width:60px;height:60px;font-size:23px">${esc(u.name[0])}</div><div style="flex:1"><h2>${esc(u.name)}</h2><span class="badge">${roleName(u.role)}</span></div></div><div class="section grid stats">${stat('XP',u.xp||0,'امتیاز کل','✦')}${stat('سطح',Math.floor((u.xp||0)/100)+1,'سطح فعلی','↗')}</div></article><article class="card"><h2 class="card-title">دستاوردها</h2><div class="list-row">🌱 شروع یادگیری <span class="badge green">فعال</span></div><div class="list-row">🔥 زنجیره چهارروزه <span class="badge amber">در مسیر</span></div><div class="list-row">🏅 پایان دوره <span class="badge">قفل</span></div></article></section>`,'پروفایل','نمایش دستاوردها و اطلاعات یادگیری')}
function managePage(){
 const les=allLessons(),c=activeCourse(),labels=moduleNamesForCourse();
 return shell('manage',`<div class="notice">محتوای درس در این دمو در مرورگر ذخیره می‌شود. ویدیوها در Cloudinary میزبانی می‌شوند و فهرست و تأیید آن‌ها در backend مشترک است.</div><div class="row"><h2>فهرست درس‌ها</h2><button class="btn primary" onclick="newLesson()">+ افزودن درس</button></div><section class="grid two"><article class="card"><div class="row"><h2 class="card-title">${esc(c.title)} · ${les.length} درس</h2><span class="badge green">منتشرشده</span></div>${les.map(l=>`<div class="lesson-row"><span class="lesson-num">${l.module}</span><div class="lesson-desc"><b>${esc(l.name)}</b><div class="muted" style="font-size:11px">فصل ${l.module} · ${db.drafts[l.id]?'پیش‌نویس ویرایش‌شده':'منتشرشده'}</div></div><button class="btn" onclick="editLesson('${l.id}')">ویرایش</button></div>`).join('')}<button class="btn" onclick="toast('همه درس‌های این دوره در همین فهرست نمایش داده شده‌اند.')">همه درس‌ها نمایش داده شد</button></article><aside class="card"><h2 class="card-title">ساختار درس‌ها</h2><p class="muted">هر درس می‌تواند متن، عنوان، کد، نکته، تمرین و آزمون داشته باشد.</p><div class="notice">برای افزودن ویدیو، یک درس را باز کنید؛ بارگذاری در بخش رسانه داخل سازنده همان درس است.</div><h3>فصل‌های دوره</h3>${labels.map((label,i)=>`<div class="list-row">فصل ${i+1} · ${esc(label)}</div>`).join('')}<h3>دستیار تولید محتوا</h3><div class="notice">پیش‌نویس‌ها بر اساس درس مرجع و راهنمای مدرس ساخته می‌شوند؛ مدرس آن‌ها را بازبینی می‌کند.</div><button class="btn" onclick="go('ai-studio')">رفتن به استودیو</button></aside></section>`, 'مدیریت دوره', c.title);
}function newLesson(){let title=prompt('عنوان درس جدید را وارد کنید:');if(!title)return;let id='custom-'+Date.now(),l={id,name:title,module:10,blocks:[{type:'heading',text:title},{type:'text',text:'پیش‌نویس درس جدید'}],exercise:{prompt:'شرح تمرین را وارد کنید',starter:'',expected:''},quiz:[{q:'سؤال نمونه',choices:['گزینه ۱','گزینه ۲','گزینه ۳'],answer:0}]};db.courses[0].modules[9].push(l);db.drafts[id]=true;save();toast('درس به فهرست پیش‌نویس‌ها افزوده شد.');editLesson(id)}
function lessonMediaMarkup(lessonId){let items=Object.values(db.media||{}).filter(m=>m.lessonId===lessonId);return items.length?items.map(m=>`<div class="media-file-row"><span class="media-file-icon video-file-icon">▶</span><span><b>${esc(m.title||m.filename)}</b><small>${esc(m.status==='approved'?'تأییدشده':m.status==='pending-review'?'در انتظار تأیید مدیر':'ردشده')}</small></span><a class="btn" href="${esc(m.secureUrl)}" target="_blank" rel="noopener">پیش‌نمایش</a></div>`).join(''):'<p class="muted">هنوز ویدیویی برای این درس ثبت نشده است.</p>'}
function editLesson(id){let l=allLessons().find(x=>x.id===id);if(!l)return;window.editing=l;window.builderBlocks=JSON.parse(JSON.stringify(l.blocks));let lessonMediaRows=lessonMediaMarkup(l.id);shell('manage',`<div class="row"><div class="notice" style="flex:1">ویرایش در پیش‌نویس انجام می‌شود؛ محتوای منتشرشده تا انتخاب «انتشار» تغییر نمی‌کند.</div><button class="btn" onclick="go('manage')">بازگشت</button></div><article class="card"><div class="form-row"><div><label>عنوان درس</label><input class="input" id="editTitle" value="${esc(l.name)}"></div><div><label>شماره فصل</label><select id="editModule" class="select">${moduleNamesForCourse().map((x,i)=>`<option value="${i+1}" ${l.module===i+1?'selected':''}>${i+1} · ${esc(x)}</option>`).join('')}</select></div></div><h3>محتوای درس · بلوک‌ها را جابه‌جا یا ویرایش کنید</h3><div id="blocks">${renderBlocks()}</div><button class="btn" onclick="addBlock()">+ افزودن متن</button> <button class="btn" onclick="addBlock('heading')">+ عنوان</button> <button class="btn" onclick="addBlock('code')">+ کد</button> <button class="btn" onclick="addBlock('tip')">+ نکته</button><div class="section"><h3>ویدیوهای همین درس</h3><p class="muted">ویدیو مستقیماً در Cloudinary قرار می‌گیرد. پس از تأیید مدیر در صفحه این درس برای دانش‌آموزان پخش می‌شود.</p><label class="upload-dropzone"><input id="builderMediaUpload" type="file" accept="video/*,.mp4,.webm,.mov,.m4v" hidden><span class="upload-cloud-icon">↑</span><b>انتخاب ویدیوی این درس</b><small>تا ۵۰۰ مگابایت · فایل‌های بزرگ تکه‌تکه بارگذاری می‌شوند</small><span class="btn upload-select-btn">آپلود به Cloudinary</span></label><div id="builderMediaState" class="file-meta upload-state"></div><div id="builderMediaList">${lessonMediaRows}</div></div><div class="section"><h3>تمرین</h3><textarea id="editExercise" class="textarea">${esc(l.exercise.prompt)}</textarea></div><div class="section"><h3>ویرایش آزمون (سؤال اول نمونه)</h3><input class="input" id="editQuiz" value="${esc(l.quiz[0].q)}" aria-label="متن سؤال نخست"></div><div class="section"><button class="btn primary" onclick="saveDraft('${id}')">ذخیره پیش‌نویس</button> <button class="btn soft" onclick="publishDraft('${id}')">ذخیره و انتشار</button></div></article>`,'ویرایش درس','سازنده محتوا · پیش‌نویس');enableDnD();let videoInput=document.getElementById('builderMediaUpload');if(videoInput)videoInput.onchange=()=>uploadCloudinaryVideo(videoInput.files[0],l.id,'builderMediaState')}

function renderBlocks(){return builderBlocks.map((b,i)=>`<div class="block-builder" draggable="true" data-index="${i}"><div class="row"><div class="block-tools"><span class="badge">⠿ ${esc(b.type)}</span><button class="small-btn" onclick="moveBlock(${i},-1)">↑</button><button class="small-btn" onclick="moveBlock(${i},1)">↓</button><button class="small-btn" onclick="removeBlock(${i})">حذف</button></div><small class="muted">بلوک ${i+1}</small></div><textarea class="textarea" onchange="builderBlocks[${i}].text=this.value">${esc(b.text)}</textarea></div>`).join('')}
function refreshBlocks(){document.getElementById('blocks').innerHTML=renderBlocks();enableDnD()}function addBlock(type='text'){builderBlocks.push({type,text:type==='heading'?'عنوان جدید':''});refreshBlocks()}function removeBlock(i){builderBlocks.splice(i,1);refreshBlocks()}function moveBlock(i,d){let j=i+d;if(j<0||j>=builderBlocks.length)return;[builderBlocks[i],builderBlocks[j]]=[builderBlocks[j],builderBlocks[i]];refreshBlocks()}function enableDnD(){let current=null;document.querySelectorAll('.block-builder').forEach(el=>{el.ondragstart=()=>{current=+el.dataset.index;el.classList.add('dragging')};el.ondragend=()=>el.classList.remove('dragging');el.ondragover=e=>e.preventDefault();el.ondrop=e=>{e.preventDefault();let to=+el.dataset.index;if(current===null||to===current)return;let [x]=builderBlocks.splice(current,1);builderBlocks.splice(to,0,x);refreshBlocks()}})}function saveDraft(id){let l=allLessons().find(x=>x.id===id);l.name=document.getElementById('editTitle').value;l.module=Number(document.getElementById('editModule').value);l.blocks=builderBlocks;l.exercise.prompt=document.getElementById('editExercise').value;l.quiz[0].q=document.getElementById('editQuiz').value;db.drafts[id]=true;save();toast('پیش‌نویس در این مرورگر ذخیره شد.');route()}function publishDraft(id){saveDraft(id);db.drafts[id]=false;save();toast('محتوا در نسخه دمو منتشر شد.');go('manage')}
function saveAiKnowledge(){let id=document.getElementById('studioLesson').value;db.aiKnowledge=db.aiKnowledge||{guidanceByLesson:{},approvedSourcesByLesson:{}};db.aiKnowledge.guidanceByLesson=db.aiKnowledge.guidanceByLesson||{};db.aiKnowledge.approvedSourcesByLesson=db.aiKnowledge.approvedSourcesByLesson||{};db.aiKnowledge.guidanceByLesson[id]=document.getElementById('studioGuidance').value.trim();let title=document.getElementById('studioSourceTitle').value.trim(),content=document.getElementById('studioSourceContent').value.trim();if(title&&content){let list=db.aiKnowledge.approvedSourcesByLesson[id]||[];list.push({title,content,approved:true,approvedBy:who().username,approvedAt:new Date().toISOString()});db.aiKnowledge.approvedSourcesByLesson[id]=list;document.getElementById('studioSourceTitle').value='';document.getElementById('studioSourceContent').value=''}save();window.studioLessonId=id;toast('راهنما و منبع تأییدشده در این مرورگر ذخیره شد.');aiStudio()}
function renderAiDraft(text){const sandboxHeading='محیط آزمایش پیشنهادی',headings=new Set(['عنوان درس','هدف یادگیری','پیش‌نیازها','توضیح درس','مثال آموزشی','تمرین دانش‌آموز','پرسش‌های آزمون',sandboxHeading,'پیشنهاد برای چیدمان درس']);const lines=String(text||'').split(/\r?\n/);let html='',list=false,code=false,codeLines=[];const fmt=s=>esc(s).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>');const closeList=()=>{if(list){html+='</ul>';list=false}};for(const line of lines){if(/^\s*```/.test(line)){closeList();if(code){html+='<pre class="ai-code"><code>'+esc(codeLines.join('\n'))+'</code></pre>';codeLines=[];code=false}else code=true;continue}if(code){codeLines.push(line);continue}const t=line.trim();if(!t){closeList();continue}if(headings.has(t)){closeList();html+=t===sandboxHeading?'<h3 class="sandbox-suggestion-title">▣ '+fmt(t)+' <span class="badge amber">پیشنهاد برای بازبینی مدرس · بدون اجرا</span></h3>':'<h3>'+fmt(t)+'</h3>';continue}if(/^[-*]\s+/.test(t)){if(!list){html+='<ul>';list=true}html+='<li>'+fmt(t.replace(/^[-*]\s+/,''))+'</li>';continue}closeList();if(/^#{1,3}\s+/.test(t)){html+='<h3>'+fmt(t.replace(/^#{1,3}\s+/,''))+'</h3>';continue}html+='<p>'+fmt(t)+'</p>'}closeList();if(code)html+='<pre class="ai-code"><code>'+esc(codeLines.join('\n'))+'</code></pre>';return html}
function aiStudio(){let lessons=allLessons(),selectedLesson=window.studioLessonId||allLessons()[0].id,knowledge=db.aiKnowledge||{},savedGuidance=knowledge.guidanceByLesson?.[selectedLesson]||'',savedSources=knowledge.approvedSourcesByLesson?.[selectedLesson]||[];shell('ai-studio',`<section class="grid two"><article class="card"><h2 class="card-title">استودیوی هوشمند مدرس <span class="badge green">OpenRouter</span></h2><p>یک درس و موضوع را انتخاب کن تا دستیار پیش‌نویسی خوانا با مثال، تمرین، آزمون و پیشنهاد بلوک‌های درس بسازد.</p><label>درس مرجع برای ساخت پیش‌نویس</label><select class="select" id="studioLesson">${lessons.map(l=>`<option value="${l.id}" ${l.id===selectedLesson?'selected':''}>فصل ${l.module} · ${esc(l.name)}</option>`).join('')}</select><label style="display:block;margin-top:12px">موضوع درس یا مفهوم مورد نظر</label><input class="input" id="studioTopic" placeholder="مثلاً: دستور print و نمایش متن در پایتون"><label style="display:block;margin-top:12px">سطح درس</label><select class="select" id="studioLevel"><option>مقدماتی</option><option>متوسط</option><option>پیشرفته</option></select><label style="display:block;margin-top:12px">منابع، سبک تدریس و اشتباه‌های رایج دانش‌آموزان</label><textarea class="textarea" id="studioGuidance" placeholder="روش تدریس، محدودیت‌ها و اشتباه‌های پرتکرار را بنویسید.">${esc(savedGuidance)}</textarea><label style="display:block;margin-top:12px">منبع تأییدشده برای همین درس</label><input id="studioSourceTitle" class="input" placeholder="عنوان منبع یا جزوه"><textarea class="textarea" id="studioSourceContent" placeholder="فقط محتوایی را وارد کنید که مدرس بررسی و تأیید کرده است."></textarea><div class="muted">${savedSources.length} منبع تأییدشده ذخیره شده است.</div><button type="button" class="btn soft" onclick="saveAiKnowledge()">ذخیره راهنمای مدرس و تأیید منبع</button><div id="studioResult" class="notice ai-draft-output">پیش‌نویس برای بازبینی مدرس است؛ تا وقتی خودتان در سازنده درس وارد نکنید، چیزی منتشر نمی‌شود.</div><button id="studioGenerate" class="btn primary">ساخت پیش‌نویس درس</button><button id="studioSave" class="btn" hidden>ذخیره پیش‌نویس در همین مرورگر</button></article><aside class="card"><h2 class="card-title">روند کار</h2><div class="list-row">۱ · انتخاب درس مرجع و موضوع جدید</div><div class="list-row">۲ · افزودن سبک تدریس و اشتباه‌های پرتکرار</div><div class="list-row">۳ · بازبینی مثال، تمرین و آزمون پیشنهادی</div><div class="list-row">۴ · انتقال بخش‌های مناسب به سازنده درس</div><p class="muted">دستیار پیش‌نویس می‌سازد؛ ذخیره محلی یا انتشار آن فقط با تصمیم مدرس است.</p></aside></section>`,'استودیوی هوشمند','ساخت پیش‌نویس آموزشی');document.getElementById('studioLesson').onchange=e=>{window.studioLessonId=e.target.value;aiStudio()};let btn=document.getElementById('studioGenerate'),out=document.getElementById('studioResult'),saveBtn=document.getElementById('studioSave');btn.onclick=async()=>{let topic=document.getElementById('studioTopic').value.trim();if(!topic){out.textContent='برای ساخت پیش‌نویس، موضوع مشخصی وارد کنید. درس انتخاب‌شده فقط منبع زمینه‌ای است.';document.getElementById('studioTopic').focus();return}btn.disabled=true;saveBtn.hidden=true;out.textContent='در حال درخواست از دستیار هوشمند…';try{let lesson=allLessons().find(l=>l.id===document.getElementById('studioLesson').value)||allLessons()[0];let result=await api('/api/ai',{mode:'teacher',topic,level:document.getElementById('studioLevel').value,role:who().role,teacherGuidance:[document.getElementById('studioGuidance').value,...(db.aiKnowledge?.approvedSourcesByLesson?.[lesson.id]||[]).filter(x=>x.approved).map(x=>`Approved source ${x.title}:\n${x.content}`)].filter(Boolean).join('\n\n'),lessonTitle:lesson.name,lessonContent:[lesson.blocks.map(b=>`[${b.type}] ${b.text}`).join('\n'),`Exercise: ${lesson.exercise?.prompt||''}`,`Quiz questions: ${(lesson.quiz||[]).map(q=>q.q).join('\n')}`].join('\n\n')});window.generatedLessonDraft={topic,lessonId:lesson.id,content:result.answer};out.innerHTML=renderAiDraft(result.answer);saveBtn.hidden=false}catch(err){out.textContent=err.message}finally{btn.disabled=false}};saveBtn.onclick=()=>{let review=window.generatedLessonDraft;if(!review)return;db.aiLessonDrafts=db.aiLessonDrafts||[];db.aiLessonDrafts.unshift({id:'draft-'+Date.now(),lessonId:review.lessonId,title:review.topic,content:review.content,createdAt:new Date().toISOString()});save();saveBtn.disabled=true;saveBtn.textContent='پیش‌نویس ذخیره شد';toast('پیش‌نویس در مرورگر فعلی ذخیره شد؛ انتشار خودکار انجام نشد.')};}
function usersPage(){let media=Object.values(db.media||{});return shell('users',`<article class="card"><div class="row"><h2 class="card-title">حساب‌های نسخه نمایشی</h2><button class="btn primary" onclick="addUser()">+ ساخت حساب</button></div><div class="table-wrap"><table><thead><tr><th>نام</th><th>نام کاربری</th><th>نقش</th><th>عملیات</th></tr></thead><tbody>${db.users.map((u,i)=>`<tr><td>${esc(u.name)}</td><td>${esc(u.username)}</td><td><select class="select" onchange="changeRole(${i},this.value)">${['student','teacher','admin'].map(r=>`<option value="${r}" ${u.role===r?'selected':''}>${roleName(r)}</option>`).join('')}</select></td><td><button class="btn" onclick="resetPassword(${i})">تغییر گذرواژه</button> ${u.username!=='admin'?`<button class="btn danger" onclick="removeUser(${i})">حذف</button>`:''}</td></tr>`).join('')}</tbody></table></div><div class="notice">مدیریت حساب‌های این نسخه نمایشی هنوز محلی است.</div></article><article class="card section"><h2 class="card-title">ویدیوهای Cloudinary</h2><section class="upload-panel"><h3>آپلود ویدیو از پنل مدیر</h3><p class="muted">ویدیو در Cloudinary ذخیره و پس از آپلود در فهرست بازبینی ثبت می‌شود.</p><label>اتصال به درس</label><select id="adminUploadLesson" class="select"><option value="">ویدیوی عمومی دوره</option>${allLessons().map(l=>`<option value="${l.id}">فصل ${l.module} · ${esc(l.name)}</option>`).join('')}</select><label class="upload-dropzone"><input id="adminMediaUpload" type="file" accept="video/*,.mp4,.webm,.mov,.m4v" hidden><span class="upload-cloud-icon">↑</span><b>انتخاب فایل ویدیویی</b><small>حداکثر ۵۰۰ مگابایت · آپلود مستقیم و تکه‌ای</small></label><div id="adminMediaState" class="file-meta upload-state"></div></section>${media.length?media.map(m=>`<div class="media-file-row"><span class="media-file-icon video-file-icon">▶</span><span><b>${esc(m.filename)}</b><small>${esc(m.status==='approved'?'تأییدشده':m.status==='pending-review'?'در انتظار بررسی':'ردشده')} · ${esc(m.publicId)} · ${esc(allLessons().find(l=>l.id===m.lessonId)?.name||'ویدیوی عمومی')} · آپلودکننده: ${esc(m.uploadedBy||'نامشخص')}</small></span><a class="btn" href="${esc(m.secureUrl)}" target="_blank" rel="noopener">بازبینی</a>${m.status==='pending-review'?`<button class="btn primary" onclick="approveMedia('${esc(m.publicId)}')">تأیید و نمایش</button><button class="btn danger" onclick="rejectMedia('${esc(m.publicId)}')">رد</button>`:''}</div>`).join(''):'<div class="empty">ویدیویی در backend ثبت نشده است.</div>'}<p class="muted">وضعیت تأیید در backend محلی ذخیره می‌شود. ویدیو پس از تأیید در داشبورد دانش‌آموز نمایش داده خواهد شد.</p></article>`,'مدیریت کاربران','حساب‌های نمونه و بازبینی رسانه')}

function studentVideoCard(){if(activeCourse()?.subject==='english')return englishVideoCard();let media=Object.values(db.media||{}).filter(m=>m.status==='approved'),m=media[0];if(m)return `<section class="student-feature-video"><div class="feature-heading"><div><span class="section-eyebrow">محتوای دوره</span><h2>درس ویدیویی تو</h2></div><span class="badge green">ویدیو از Cloudinary</span></div><article class="card"><video controls playsinline preload="metadata" style="width:100%;max-height:480px;border-radius:14px;background:#101827" src="${esc(m.secureUrl)}"></video><h3>${esc(m.filename||'ویدیوی درس')}</h3><p class="muted">ویدیوی تأییدشده دوره پایتون</p></article></section>`;return `<section class="student-feature-video"><div class="feature-heading"><div><span class="section-eyebrow">از همان‌جا ادامه بده</span><h2>درس ویدیویی تو</h2></div><span class="badge">پیش‌نمایش رابط ویدیو</span></div><div class="video-feature-grid"><div class="video-preview" role="img" aria-label="پیش‌نمایش نمونه پخش درس پایتون"><div class="video-grain"></div><div class="video-code-window"><div class="window-dots"><i></i><i></i><i></i><span>lesson_03.py</span></div><pre><span class="code-purple">for</span> name <span class="code-purple">in</span> learners:
    <span class="code-blue">print</span>(<span class="code-orange">"سلام، "</span> + name)
<span class="code-comment"># هر روز یک قدم جلوتر</span></pre></div><button class="play-video" aria-label="نمونه رابط پخش ویدیو">▶</button><div class="player-topline"><span>درس ۳ · حلقه‌ها</span><span>پیش‌نمایش نمونه</span></div><div class="video-controls"><span>▶</span><span>۰۸:۴۲ / ۱۸:۳۰</span><div class="video-track"><i></i></div><span>⚙</span><span>⛶</span></div></div><div class="video-feature-info"><span class="video-label">دوره پایتون از پایه</span><h3>آشنایی با حلقه for</h3><p>یاد بگیر چطور چند کار تکراری را با چند خط کد انجام دهی.</p><div class="video-meta"><span>◷ ۱۸ دقیقه</span><span>▤ فصل پنجم</span></div><button class="btn primary" onclick="go('lesson',{id:'l5-1'})">رفتن به درس <span>←</span></button><div class="video-next"><span class="next-icon">✓</span><span><b>آخرین بازدید</b><small>پیشرفت تماشای نمونه: ۴۷٪</small></span></div></div></div></section>`}
function teacherTimeChart(){let vals=[38,56,42,82,68,94,60],labs=['ش','ی','د','س','چ','پ','ج'];return `<div class="teacher-time-chart" role="img" aria-label="نمودار نمونه زمان حضور هفتگی">${vals.map((v,i)=>`<div class="time-column"><small>${['۱٫۲','۱٫۸','۱٫۴','۲٫۶','۲٫۱','۳٫۰','۱٫۹'][i]}h</small><i style="height:${v}%"></i><span>${labs[i]}</span></div>`).join('')}</div><div class="chart-caption">ساعت مطالعه روزانه · داده نمایشی</div>`}
function teacherDashboard(){let students=db.users.filter(u=>u.role==='student'),records=[];return shell('dashboard',`<section class="welcome-hero teacher-hero"><div><span class="hero-eyebrow">نمای مدرس · ترم پاییز</span><h2>سلام ${esc(who().name)}،<br>کلاس دارد خوب پیش می‌رود.</h2><p>وضعیت درس‌ها، آزمون‌ها و روند یادگیری دانش‌آموزان را یک‌جا ببین.</p><button class="btn hero-button" onclick="go('manage')">رفتن به فضای تدریس <span>←</span></button></div><div class="hero-art"><div class="hero-orbit orbit-one"></div><div class="hero-orbit orbit-two"></div><div class="teacher-hero-icon"><svg viewBox="0 0 64 64" aria-hidden="true"><path d="M6 23 32 10l26 13-26 13L6 23Z"/><path d="M17 29v13c8 7 22 7 30 0V29M57 24v17"/><circle cx="57" cy="44" r="3"/></svg></div><div class="floating-code">class Learning:</div></div></section><section class="grid stats">${stat('دانش‌آموزان',students.length||3,'در دوره پایتون از پایه','♙')}${stat('میانگین پیشرفت','۶۸٪','+۸٪ نسبت به هفته قبل','↗')}${stat('میانگین آزمون','۷۸ از ۱۰۰','در آزمون‌های اخیر','✓')}${stat('زمان یادگیری','۱۲٫۴ ساعت','این هفته · نمونه نمایشی','◷')}</section><section class="teacher-analytics-grid"><article class="card teacher-chart-card"><div class="row"><div><span class="section-eyebrow">تعامل در کلاس</span><h2 class="card-title">زمان یادگیری دانش‌آموزان</h2></div><select class="select compact-select" aria-label="بازه زمانی"><option>این هفته</option><option>ماه جاری</option></select></div>${teacherTimeChart()}<div class="chart-footer-stat"><span><i class="legend-dot green-dot"></i>میانگین حضور روزانه</span><b>۱ ساعت و ۴۶ دقیقه</b></div></article><article class="card teacher-progress-card"><div class="row"><div><span class="section-eyebrow">پیشرفت دوره</span><h2 class="card-title">روند یادگیری</h2></div><span class="trend-chip">↗ رو به رشد</span></div><div class="progress-summary"><strong>۶۸٪</strong><span>میانگین تکمیل درس‌ها</span></div><div class="progress"><span style="width:68%"></span></div><div class="progress-breakdown"><div><span>تکمیل‌شده</span><b>۱۸ درس</b></div><div><span>در حال یادگیری</span><b>۶ درس</b></div><div><span>شروع‌نشده</span><b>۳ درس</b></div></div><div class="topic-tags"><span class="badge green">متغیرها · خوب</span><span class="badge amber">حلقه‌ها · نیاز به تمرین</span></div></article></section><section class="card recent-results"><div class="row recent-heading"><div><span class="section-eyebrow">آخرین فعالیت‌ها</span><h2 class="card-title">نتیجه آزمون‌های اخیر</h2></div><button class="btn soft" onclick="go('reports')">همه گزارش‌ها ←</button></div><div class="recent-test-list">${records.map(r=>`<div class="recent-test-row"><div class="student-cell"><span class="avatar">${r.avatar}</span><span><b>${r.name}</b><small>${r.time}</small></span></div><div class="test-cell"><b>${r.lesson}</b><small>دوره پایتون از پایه</small></div><div class="result-meter"><div class="mini-track"><i style="width:${r.score}%"></i></div><span>${r.score}٪</span></div><span class="badge ${r.score>=80?'green':r.score>=70?'':'amber'}">${r.score>=80?'عالی':r.score>=70?'خوب':'نیازمند مرور'}</span></div>`).join('')}</div><p class="sample-note">اطلاعات آزمون و حضور این بخش نمونه‌ای است تا چیدمان پنل مدرس را نشان دهد.</p></section><section class="teacher-shortcuts"><button class="teacher-shortcut" onclick="go('manage')"><span>▣</span><b>مدیریت درس‌ها</b><small>محتوا و رسانه‌ها</small></button><button class="teacher-shortcut" onclick="go('students')"><span>♙</span><b>دانش‌آموزان</b><small>مشاهده روند یادگیری</small></button><button class="teacher-shortcut" onclick="go('ai-studio')"><span>✦</span><b>استودیوی مدرس</b><small>ابزار AI آماده اتصال</small></button></section>`,`داشبورد مدرس`,`آمار دوره، آزمون‌ها و زمان یادگیری`)}
async function refreshSharedMedia(){if(!who())return;const result=await api(`/api/media?role=${encodeURIComponent(who().role)}`);db.media=Object.fromEntries((result.media||[]).map(item=>[item.publicId,item]));save()}
async function route(){if(!db.user||!who()){loginView();return}try{await refreshSharedMedia()}catch{}let [page,id]=location.hash.replace(/^#\/?/,'').split('/');if(!page)page='dashboard';let u=who(),allowed=navByRole[u.role].map(n=>n[0]);if(!allowed.includes(page)&&!['course','lesson'].includes(page)){page='dashboard'}if(page==='dashboard')dashboard();else if(page==='course')coursePage();else if(page==='courses')coursesPage();else if(page==='lesson')lessonPage(id);else if(page==='progress')progressPage();else if(page==='knowledge')knowledgePage();else if(page==='tutor')tutorPage(id);else if(page==='profile')profilePage();else if(page==='manage')managePage();else if(page==='ai-studio')aiStudio();else if(page==='users')usersPage();else if(page==='reports')reportPage();else if(page==='students')studentsPage();else dashboard();let q=document.getElementById('quizForm');if(q)q.onsubmit=e=>submitQuiz(e,id);let f=document.getElementById('mediaUpload');if(f)f.onchange=()=>uploadCloudinaryVideo(f.files[0],document.getElementById('mediaLesson')?.value||'','mediaState');let af=document.getElementById('adminMediaUpload');if(af)af.onchange=()=>uploadCloudinaryVideo(af.files[0],document.getElementById('adminUploadLesson')?.value||'','adminMediaState')}
async function uploadCloudinaryVideo(file,lessonId='',stateId='mediaState'){let out=document.getElementById(stateId);if(!file)return;if(!file.type.startsWith('video/')&&!/\.(mp4|webm|mov|m4v|ogg)$/i.test(file.name)){out.textContent='فرمت فایل ویدیویی شناخته نشد. فایل MP4، WebM یا MOV انتخاب کنید.';return}if(file.size>500*1024*1024){out.textContent='حداکثر اندازه فایل در این دمو ۵۰۰ مگابایت است.';return}out.textContent='در حال آماده‌سازی آپلود امن…';let cloudUploadComplete=false;try{let signed=await api('/api/media/sign',{resourceType:'video',filename:file.name});if(signed.provider!=='cloudinary')throw new Error('برای این ارائه‌دهنده، رابط بارگذاری اختصاصی هنوز باید اضافه شود.');const endpoint=`https://api.cloudinary.com/v1_1/${encodeURIComponent(signed.cloudName)}/video/upload`;const chunkSize=20*1024*1024,chunked=file.size>100*1024*1024,uploadId=crypto.randomUUID();let data=null;for(let start=0;start<file.size;start+=chunked?chunkSize:file.size){let end=Math.min(start+(chunked?chunkSize:file.size),file.size),form=new FormData();form.append('file',file.slice(start,end),file.name);form.append('api_key',signed.apiKey);form.append('timestamp',String(signed.timestamp));form.append('signature',signed.signature);form.append('folder',signed.folder);form.append('use_filename','true');form.append('filename_override',signed.params.filename_override);let headers={};if(chunked){headers['X-Unique-Upload-Id']=uploadId;headers['Content-Range']=`bytes ${start}-${end-1}/${file.size}`}out.textContent=chunked?`در حال بارگذاری ویدیو به Cloudinary… ${Math.round(end/file.size*100)}٪`:'در حال بارگذاری مستقیم ویدیو به Cloudinary…';let response=await fetch(endpoint,{method:'POST',headers,body:form});data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error?.message||`Cloudinary آپلود را نپذیرفت (${response.status}).`)}if(!data?.public_id||!data?.secure_url)throw new Error('Cloudinary آپلود را کامل نکرد؛ پاسخ نهایی ویدیو دریافت نشد.');cloudUploadComplete=true;out.textContent='ویدیو در فضای ابری آپلود شد؛ در حال ثبت برای بازبینی مدیر…';await api('/api/media',{role:who().role,username:who().username,publicId:data.public_id,secureUrl:data.secure_url,filename:file.name,title:file.name,lessonId, duration:data.duration||0,bytes:data.bytes||file.size});await refreshSharedMedia();out.textContent=`آپلود شد: ${file.name} · تا تأیید مدیر برای دانش‌آموز نمایش داده نمی‌شود.`;toast('ویدیو ذخیره و برای بازبینی ثبت شد.');if(stateId==='builderMediaState'){let list=document.getElementById('builderMediaList');if(list)list.innerHTML=lessonMediaMarkup(lessonId)}else await route()}catch(err){out.textContent=err instanceof TypeError?'اتصال به فضای ابری برقرار نشد. اتصال اینترنت یا محدودیت شبکه را بررسی کنید؛ آپلود کامل نشد.':cloudUploadComplete?`ویدیو آپلود شد اما ثبت آن در کتابخانه برنامه ناموفق بود: ${err.message}`:(err.message||'آپلود یا ثبت ویدیو ناموفق بود.')}}
async function approveMedia(id){try{await api(`/api/media/${encodeURIComponent(id)}/review`,{role:who().role,username:who().username,status:'approved'});await refreshSharedMedia();await route();toast('ویدیو تأیید شد و برای دانش‌آموزان قابل مشاهده است.')}catch(err){toast(err.message)}}async function rejectMedia(id){try{await api(`/api/media/${encodeURIComponent(id)}/review`,{role:who().role,username:who().username,status:'rejected'});await refreshSharedMedia();await route();toast('ویدیو رد شد؛ فایل Cloudinary حذف نشده است.')}catch(err){toast(err.message)}}
async function logout(){try{await api('/api/auth/logout',{})}catch{}db.user=null;save();catalogView()}window.addEventListener('hashchange',route);

