let novaStudyTimer=null,novaStudySeconds=0,novaStudySession=sessionStorage.getItem('nova-study-session')||crypto.randomUUID();
sessionStorage.setItem('nova-study-session',novaStudySession);
async function initNovaAuth(){try{const result=await api('/api/auth/me');if(!result.user){catalogView();return}const old=db.users.find(u=>u.username===result.user.username)||{};db.users=[{...old,...result.user}];db.user=result.user.username;save();await route()}catch{db.user=null;catalogView()}}
const novaTours={
  student:[['.welcome-hero','مسیر یادگیری','از اینجا درس بعدی را ادامه بده و وضعیت دوره‌ات را ببین.'],['[data-page="courses"]','دوره‌ها و درس‌ها','دوره را باز کن، درس بخوان، ویدیو ببین و تمرین‌ها را انجام بده.'],['[data-page="tutor"]','یار آموزشی','درباره همین درس سؤال بپرس و برای کد یا تمرین راهنمایی بگیر.'],['[data-page="progress"]','پیشرفت','نتایج آزمون‌ها و روند یادگیری خودت را بررسی کن.']],
  teacher:[['.welcome-hero','داشبورد مدرس','اینجا خلاصه فعالیت کلاس و آمار دانش‌آموزها را می‌بینی.'],['[data-page="manage"]','ساخت و مدیریت درس','درس‌ها را ویرایش کن، آزمون بساز و ویدیو یا منبع اضافه کن.'],['[data-page="students"]','دانش‌آموزان','زمان مطالعه و نتیجه آزمون هر دانش‌آموز را پیگیری کن.'],['[data-page="ai-studio"]','استودیوی هوشمند','از دستیار برای تهیه پیش‌نویس درس و تمرین کمک بگیر؛ قبل از انتشار بازبینی کن.']],
  admin:[['.welcome-hero','داشبورد مدیر','نمای کلی و میانبرهای مدیریت در این بخش قرار دارد.'],['[data-page="users"]','حساب‌ها و رسانه','حساب‌ها و محتوای بارگذاری‌شده را مدیریت و بررسی کن.'],['[data-page="manage"]','محتوای دوره','دوره‌ها و درس‌های منتشرشده را مرور کن.']]};
function closeNovaTour(mark=true){document.querySelector('.nova-tour-backdrop')?.remove();document.querySelector('.nova-tour-focus')?.classList.remove('nova-tour-focus');if(mark&&who())localStorage.setItem(`nova-tour-seen:${who().username}`,'1')}
function showNovaTour(index=0){let user=who(),steps=novaTours[user?.role]||[];if(!user||index>=steps.length){closeNovaTour();return}closeNovaTour(false);let [selector,title,description]=steps[index],target=document.querySelector(selector)||document.querySelector('.topbar');target?.scrollIntoView({behavior:'smooth',block:'center'});target?.classList.add('nova-tour-focus');let overlay=document.createElement('div');overlay.className='nova-tour-backdrop';overlay.innerHTML=`<section class="nova-tour-card" role="dialog" aria-modal="true" aria-labelledby="novaTourTitle"><span class="section-eyebrow">راهنمای شروع · ${index+1} از ${steps.length}</span><h2 id="novaTourTitle">${title}</h2><p>${description}</p><div class="nova-tour-actions"><button class="btn soft" data-tour-skip>بعداً</button><button class="btn primary" data-tour-next>${index===steps.length-1?'پایان راهنما':'بعدی ←'}</button></div></section>`;document.body.append(overlay);overlay.querySelector('[data-tour-skip]').onclick=()=>closeNovaTour();overlay.querySelector('[data-tour-next]').onclick=()=>showNovaTour(index+1)}
let novaLastHeartbeat=Date.now();document.addEventListener('visibilitychange',()=>{novaLastHeartbeat=Date.now()});
function startNovaStudyTimer(){if(novaStudyTimer||!who())return;novaStudyTimer=setInterval(async()=>{const now=Date.now(),elapsed=Math.min(120,Math.floor((now-novaLastHeartbeat)/1000));novaLastHeartbeat=now;if(!who()||document.visibilityState!=='visible'||elapsed<1)return;try{await api('/api/activity/study',{sessionId:novaStudySession,seconds:elapsed,lessonId:db.currentLessonId||''})}catch{}},60000)}
async function loadTeacherAnalytics(){if(!who()||!['teacher','admin'].includes(who().role))return;const list=document.querySelector('.recent-test-list');if(!list||list.dataset.loaded)return;list.dataset.loaded='1';try{const result=await api('/api/activity/study');list.innerHTML=result.students.length?result.students.map(s=>{const hours=(Number(s.week_seconds||0)/3600).toFixed(1),score=s.average_score==null?'—':`${s.average_score}%`,when=s.latest_at?new Date(s.latest_at).toLocaleDateString():'بدون آزمون';return `<div class="recent-test-row"><div class="student-cell"><span class="avatar">${esc((s.display_name||'?')[0])}</span><span><b>${esc(s.display_name)}</b><small>${hours} ساعت مطالعه در ۷ روز اخیر</small></span></div><div class="test-cell"><b>${s.quiz_count} آزمون ثبت‌شده</b><small>آخرین نتیجه: ${score} · ${esc(when)}</small></div><div class="result-meter"><div class="mini-track"><i style="width:${Math.max(0,Math.min(100,Number(s.average_score)||0))}%"></i></div><span>${score}</span></div><span class="badge">کل مطالعه ${(Number(s.study_seconds||0)/3600).toFixed(1)} ساعت</span></div>`}).join(''):'<div class="empty">هنوز دانش‌آموز فعالی به این مدرس اختصاص نیافته یا فعالیتی ثبت نشده است.</div>';const note=document.querySelector('.sample-note');if(note)note.textContent='آمار از زمان مطالعه و تلاش‌های آزمون ثبت‌شده در پایگاه داده خوانده می‌شود.'}catch(error){list.dataset.loaded='';list.innerHTML='<div class="notice">گزارش زنده پس از اتصال پایگاه داده و ثبت فعالیت دانش‌آموز در دسترس است.</div>';const note=document.querySelector('.sample-note');if(note)note.textContent='داده نمونه نمایش داده نمی‌شود.'}}
function novaLoginGuides(){if(!who())return;startNovaStudyTimer();if(document.querySelector('.recent-test-list'))loadTeacherAnalytics();const key=`nova-tour-seen:${who().username}`;if(!localStorage.getItem(key)&&!document.querySelector('.nova-tour-backdrop'))showNovaTour()}
const novaAppRoot=document.getElementById('app');if(novaAppRoot)new MutationObserver(()=>setTimeout(novaLoginGuides,80)).observe(novaAppRoot,{childList:true});setTimeout(novaLoginGuides,120);

